export function encode(v) {
  const out = new Out();
  writeResolveResult(out, v, 0);
  out.byte(0x0a);
  return out.bytes();
}

// A BOM inside a JSON string is data, not a stream signature.
const DEC = new TextDecoder("utf-8", {ignoreBOM: true});
const DEPTH_LIMIT = 64;
const I64_DIGITS = 19;
const UNESCAPE = { 0x22: 0x22, 0x5c: 0x5c, 0x2f: 0x2f, 0x62: 0x08, 0x66: 0x0c, 0x6e: 0x0a, 0x72: 0x0d, 0x74: 0x09 };

export class Refusal extends Error {
  constructor(word, offset) {
    super("refused: " + word + " at byte " + offset);
    this.name = "Refusal";
    this.word = word;
    this.offset = offset;
  }
}

function appendRune(out, cp) {
  if (cp < 0x80) out.push(cp);
  else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
}

// TextDecoder substitutes U+FFFD for a bad sequence rather than reporting it, so
// the bytes are checked before they are decoded and the refusal says so.
function validUtf8(b) {
  for (let i = 0; i < b.length; ) {
    const c = b[i];
    if (c < 0x80) { i++; continue; }
    let n, cp;
    if (c >> 5 === 0x6) { n = 2; cp = c & 0x1f; }
    else if (c >> 4 === 0xe) { n = 3; cp = c & 0x0f; }
    else if (c >> 3 === 0x1e) { n = 4; cp = c & 0x07; }
    else return false;
    if (i + n > b.length) return false;
    for (let k = 1; k < n; k++) {
      if (b[i + k] >> 6 !== 0x2) return false;
      cp = (cp << 6) | (b[i + k] & 0x3f);
    }
    const lowest = [0, 0, 0x80, 0x800, 0x10000][n];
    if (cp < lowest || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return false;
    i += n;
  }
  return true;
}

class Reader {
  constructor(buf) { this.buf = buf; this.pos = 0; this.depth = 0; this.limit = DEPTH_LIMIT; }

  refuse(word) { return new Refusal(word, this.pos); }

  at() { return this.pos < this.buf.length ? this.buf[this.pos] : 0; }

  digit() { const c = this.at(); return c >= 0x30 && c <= 0x39; }

  ws() { while (this.pos < this.buf.length && isWs(this.buf[this.pos])) this.pos++; }

  enter() {
    this.depth++;
    if (this.depth > this.limit) throw this.refuse("depth_exceeded");
  }

  string() {
    if (this.at() !== 0x22) throw this.refuse("wrong_type");
    this.pos++;
    const out = [];
    for (;;) {
      if (this.pos >= this.buf.length) throw this.refuse("malformed");
      const c = this.buf[this.pos];
      if (c === 0x22) {
        this.pos++;
        const bytes = Uint8Array.from(out);
        if (!validUtf8(bytes)) throw this.refuse("bad_string");
        return DEC.decode(bytes);
      }
      if (c < 0x20) throw this.refuse("bad_string");
      if (c === 0x5c) this.escape(out);
      else { out.push(c); this.pos++; }
    }
  }

  escape(out) {
    this.pos++;
    if (this.pos >= this.buf.length) throw this.refuse("malformed");
    const c = this.buf[this.pos];
    this.pos++;
    const plain = UNESCAPE[c];
    if (plain !== undefined) { out.push(plain); return; }
    if (c !== 0x75) throw this.refuse("bad_string");
    let u = this.hex4();
    if (u >= 0xdc00 && u <= 0xdfff) throw this.refuse("bad_string");
    if (u >= 0xd800 && u <= 0xdbff) {
      if (this.pos + 1 >= this.buf.length || this.buf[this.pos] !== 0x5c || this.buf[this.pos + 1] !== 0x75)
        throw this.refuse("bad_string");
      this.pos += 2;
      const low = this.hex4();
      if (low < 0xdc00 || low > 0xdfff) throw this.refuse("bad_string");
      u = 0x10000 + ((u - 0xd800) << 10) + (low - 0xdc00);
    }
    appendRune(out, u);
  }

  hex4() {
    if (this.pos + 4 > this.buf.length) throw this.refuse("bad_string");
    let u = 0;
    for (let i = 0; i < 4; i++) {
      const c = this.buf[this.pos + i];
      if (c >= 0x30 && c <= 0x39) u = (u << 4) | (c - 0x30);
      else if (c >= 0x61 && c <= 0x66) u = (u << 4) | (c - 0x61 + 10);
      else if (c >= 0x41 && c <= 0x46) u = (u << 4) | (c - 0x41 + 10);
      else throw this.refuse("bad_string");
    }
    this.pos += 4;
    return u;
  }

  integer(low, high) {
    const c = this.at();
    if (c !== 0x2d && (c < 0x30 || c > 0x39)) throw this.refuse("wrong_type");
    const negative = c === 0x2d;
    if (negative) this.pos++;
    if (!this.digit()) throw this.refuse("malformed");
    const start = this.pos;
    if (this.at() === 0x30) this.pos++;
    else while (this.digit()) this.pos++;
    const after = this.at();
    if (after === 0x2e || after === 0x65 || after === 0x45 || this.digit()) throw this.refuse("number_spelling");
    if (this.pos - start > I64_DIGITS) throw this.refuse("number_spelling");
    let n = BigInt(String.fromCharCode(...this.buf.subarray(start, this.pos)));
    if (negative) {
      if (n === 0n) throw this.refuse("number_spelling");
      n = -n;
    }
    if (n < low || n > high) throw this.refuse("number_spelling");
    return n;
  }

  boolean() {
    if (this.at() === 0x74) { this.literal("true"); return true; }
    if (this.at() === 0x66) { this.literal("false"); return false; }
    throw this.refuse("wrong_type");
  }

  literal(word) {
    for (let i = 0; i < word.length; i++)
      if (this.buf[this.pos + i] !== word.charCodeAt(i)) throw this.refuse("malformed");
    this.pos += word.length;
  }

  strList() {
    if (this.at() !== 0x5b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = [];
    this.ws();
    if (this.at() !== 0x5d) {
      for (;;) {
        this.ws();
        out.push(this.string());
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x5d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawMap() {
    if (this.at() !== 0x7b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = Object.create(null);
    this.ws();
    if (this.at() !== 0x7d) {
      for (;;) {
        this.ws();
        if (this.at() !== 0x22) throw this.refuse("malformed");
        const k = this.string();
        if (k in out) throw this.refuse("duplicate_key");
        this.ws();
        if (this.at() !== 0x3a) throw this.refuse("malformed");
        this.pos++;
        this.ws();
        out[k] = this.rawValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x7d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawValue() {
    const start = this.pos;
    this.skipValue();
    return this.buf.subarray(start, this.pos);
  }

  skipValue() {
    const c = this.at();
    if (c === 0x22) this.skipString();
    else if (c === 0x7b || c === 0x5b) this.skipContainer();
    else if (c === 0x74) this.literal("true");
    else if (c === 0x66) this.literal("false");
    else if (c === 0x6e) this.literal("null");
    else if (c === 0x2d || (c >= 0x30 && c <= 0x39)) this.skipNumber();
    else throw this.refuse("malformed");
  }

  // An opaque value is validated and carried, never interpreted. Its syntax is
  // the record's own — the same string reader, so an escape, a control byte or a
  // lone surrogate is judged identically at any depth — and what it is free to
  // spell, it keeps: the bytes between these two offsets are what a writer
  // re-emits. A number is walked, never converted, so a value no host type holds
  // survives the reader that carried it.
  skipString() {
    this.string();
  }

  someDigits() {
    let n = 0;
    while (this.at() >= 0x30 && this.at() <= 0x39) { this.pos++; n++; }
    if (n === 0) throw this.refuse("number_spelling");
  }

  skipNumber() {
    if (this.at() === 0x2d) this.pos++;
    const c = this.at();
    if (c === 0x30) this.pos++;
    else if (c > 0x30 && c <= 0x39) { while (this.at() >= 0x30 && this.at() <= 0x39) this.pos++; }
    else throw this.refuse("number_spelling");
    if (this.at() === 0x2e) { this.pos++; this.someDigits(); }
    if (this.at() === 0x65 || this.at() === 0x45) {
      this.pos++;
      if (this.at() === 0x2b || this.at() === 0x2d) this.pos++;
      this.someDigits();
    }
  }

  skipContainer() {
    const opener = this.at();
    const shut = opener === 0x7b ? 0x7d : 0x5d;
    this.enter();
    this.pos++;
    this.ws();
    const seen = new Set();
    if (this.at() !== shut) {
      for (;;) {
        this.ws();
        if (opener === 0x7b) {
          if (this.at() !== 0x22) throw this.refuse("malformed");
          const k = this.string();
          if (seen.has(k)) throw this.refuse("duplicate_key");
          seen.add(k);
          this.ws();
          if (this.at() !== 0x3a) throw this.refuse("malformed");
          this.pos++;
          this.ws();
        }
        this.skipValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== shut) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
  }
}

function strMap(r) {
  if (r.at() !== 0x7b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = Object.create(null);
  r.ws();
  if (r.at() !== 0x7d) {
    for (;;) {
      r.ws();
      if (r.at() !== 0x22) throw r.refuse("malformed");
      const k = r.string();
      if (k in out) throw r.refuse("duplicate_key");
      r.ws();
      if (r.at() !== 0x3a) throw r.refuse("malformed");
      r.pos++;
      r.ws();
      out[k] = r.string();
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x7d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

function readList(r, elem) {
  if (r.at() !== 0x5b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = [];
  r.ws();
  if (r.at() !== 0x5d) {
    for (;;) {
      r.ws();
      out.push(elem(r));
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x5d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

// Capability and acceptable contract identities, required guarantees and
// permitted placement. Contains no caller identity or provider preference.
// Contract list must be nonempty; guarantees may be empty.
export function newResolveRequest() {
  return { capability: "", contracts: [], guarantees: [], scope: "" };
}

// [ServiceReference](https://openabstractions.github.io/reference.html#concept-facade.service-reference):
// A candidate service binding, not acceptance or authority. Provider identifies
// a logical provider, not a PID. Scope is the concrete execution placement,
// local or remote; transport and endpoint describe the application connection.
// Both placements can bind a local OA endpoint whose service enforces that
// placement. Contract is an exact versioned service identity; endpoint is
// opaque to application code.
export function newServiceReference() {
  return { provider: "", capability: "", contract: "", guarantees: [], scope: "", transport: "", endpoint: "" };
}

// Reference is present exactly when resolved. Failure status describes the
// first unsatisfied resolution stage without exposing disallowed provider
// metadata. Service authentication and acceptance remain necessary after
// resolution.
export function newResolveResult() {
  return { status: "", reference: null };
}

// Read-only platform registration or supervisor evidence. Unknown means
// observation is unavailable; unavailable requires actual evidence that the
// selected registration is absent. Installed and starting require registration
// or supervisor evidence. Running describes a supervisor process and does not
// establish capability readiness. A missing endpoint alone establishes none of
// these states. Detail is diagnostic text, never authority or a recovery
// instruction.
export function newBootstrapObservation() {
  return { state: "", detail: "" };
}

// One authorized resolver observation. An absent result means unobserved
// because the query was not completed; it does not imply unavailable. Existing
// resolution statuses and disclosure rules apply unchanged. A resolved
// reference remains a candidate binding, not proof of successful provider
// calls.
export function newCapabilityObservation() {
  return { request: newResolveRequest(), result: null };
}

// Client-composed point-in-time diagnostics, with no new service or activation
// operation. Platform evidence is explicit and may be unknown. Capability
// queries use one caller waiting budget and authority; observations are
// sequential and not an atomic snapshot. Transport or cancellation errors are
// reported separately by the language observation API; unanswered entries
// retain absent results.
export function newRuntimeObservation() {
  return { bootstrap: newBootstrapObservation(), capabilities: [] };
}

// One native Peer attribute: user, process, path, package or code, in that
// order. proof is the abstraction.identity Proof name the receiving boundary
// established for this connection's caller. ceiling is the best Proof name the
// receiving platform's transport can reach for that attribute. Both are
// asserted by the receiving runtime and are display words, never authority.
export function newCallerAttribute() {
  return { attribute: "", proof: "", ceiling: "" };
}

// The receiving runtime's assertion of how it bound the caller. mechanism names
// the establishing facility as the logging service stamp does, identity/<os>.
// account is the Windows SID or the decimal POSIX uid, and program the
// executable path, each at the proof its attribute reports. pid is -1 where
// unestablished. platform, transport, bindable and stronger restate the
// receiving platform's identity ceiling: whether a binding pins the caller's
// process, and which transport would prove more (empty when none). Only
// observed carries identity; forbidden, unavailable and invalid carry empty
// strings, pid -1, no attributes, and bindable false.
export function newCallerObservation() {
  return { outcome: "", mechanism: "", account: "", program: "", pid: 0n, attributes: [], platform: "", transport: "", bindable: false, stronger: "" };
}

// [ServiceState](https://openabstractions.github.io/reference.html#concept-facade.endpoint-service-state):
// one service an endpoint hosts. contract is its wire name. readiness is ready
// unless the handler's readiness hook reports otherwise; why names the reason
// when it is not ready and is empty when ready. guarantees are those the
// provider states for the service. capabilities is an open map of display
// facts, such as profiles: chat,embed. None of it is authority.
export function newServiceState() {
  return { contract: "", readiness: "", why: "", guarantees: [], capabilities: {} };
}

// [Description](https://openabstractions.github.io/reference.html#concept-facade.endpoint-description):
// described lists every service the endpoint hosts, in the endpoint's order.
// program and version are the display name and version the provider gives
// itself, possibly empty, and never authority: the caller binds the server by
// its own connection proof. forbidden is reserved for a boundary policy that
// withholds the description, unavailable for an endpoint that cannot describe
// itself now, and invalid for a request it cannot interpret. Refusals carry
// empty strings and no services.
export function newDescription() {
  return { outcome: "", program: "", version: "", services: [] };
}

// [RemoteTrust](https://openabstractions.github.io/reference.html#concept-facade.registry-remote-trust):
// The explicit mutual-TLS trust of a remote runtime. server_name is the name
// its certificate must carry. roots, certificate and key are absolute paths of
// PEM files on this machine: the roots trusted for that server, and this
// runtime's client certificate and private key, which the remote maps to its
// own caller. credential, when present, names the abstraction.credentials
// record the remote holds and applies to requests delegated to it. The paths
// are configuration; no key material travels in registry@1.
export function newRemoteTrust() {
  return { serverName: "", roots: "", certificate: "", key: "", credential: "" };
}

// The daily limits of the credential a host declaration names, per UTC day, in
// the units abstraction.inference/operator@1 CeilingLimit uses: tokens, spend
// in currency millionths, requests, images, audio seconds and characters. Zero
// or absent means no limit in that unit.
export function newDeclarationCeiling() {
  return { tokensPerDay: 0n, microsPerDay: 0n, requestsPerDay: 0n, imagesPerDay: 0n, audioSecondsPerDay: 0n, charactersPerDay: 0n };
}

// The foreign HTTP engine a declaration of role host names, the fields
// abstraction.inference/operator@1 HostEntry carries. base is its https or
// loopback http API root, with no user information, query or fragment. kind is
// the wire it speaks: an inference local_host_kinds member for a local engine,
// and a router wire kind or <owner>/<name>@<n> for a hosted one. hosted false
// is an engine on this machine, which carries no credential and no ceiling;
// hosted true is a provider endpoint off it, whose credential names the
// abstraction.credentials record the service applies and whose ceiling limits
// that credential. The profiles the host serves are its profile:<name>
// resources.
export function newDeclarationHost() {
  return { base: "", kind: "", hosted: false, credential: "", ceiling: null };
}

// One required inference extension key a provider or remote runtime asserts it
// can examine for a declared profile. This operator-managed inventory lets the
// selecting runtime refuse unknown required keys before activating a provider;
// the selected service still validates values and model-specific support before
// accepting work.
export function newDeclarationExtension() {
  return { profile: "", key: "" };
}

// One program the runtime knows. name is 1..64 bytes of a-z 0-9 _ - and unique.
// role names what it is, and each role validates its own fields (FAC-R6). A
// provider declares program, the absolute executable path the runtime launches
// and requires of the process serving endpoint, arguments of 0..64 strings of
// 1..4096 bytes with {endpoint} replaced by endpoint, endpoint a local endpoint
// name of 1..64 bytes of a-z 0-9 _ . -, transport oa-native@1, activation
// on_demand or attach, and contracts of 1..16 distinct wire names of generated
// services it serves. A remote declares transport oa-remote@1, activation
// remote, endpoint tls://<host>:<port>, the trust record in remote, and no
// program or arguments. A host declares transport http@1, activation attach,
// the engine in host, and no program, arguments, endpoint, contracts,
// guarantees, models or remote. guarantees holds 0..16 distinct names a
// provider's candidates advertise. resources holds 0..64 distinct <kind>:<name>
// of declaration_resource_kinds, name 1..64 bytes of a-z 0-9 _ . -;
// profile:<name> is what a host or a remote serves. models is the 0..64
// distinct model names a native inference provider is trusted to serve, each
// 1..256 UTF-8 bytes without controls; an entry <profile>:<model> whose profile
// the declaration serves (a listed profile whose contract it declares, or chat
// for a chat-only declaration listing none) serves model for that profile
// alone, any other entry serves every served profile, and a model named chat:x
// is written chat:chat:x (abstraction.router ROUTE-D9). on_demand launches
// program as a supervised child when a resolution first needs it; attach reads
// a provider something else started. Extension inventory lives in registry@2
// and is omitted from this strict registry@1 projection.
export function newDeclaration() {
  return { name: "", program: "", arguments: [], endpoint: "", transport: "", contracts: [], guarantees: [], resources: [], activation: "", remote: null, models: [], role: "", host: null };
}

// One atomic registry@2 edit. The extension inventory is validated against the
// declaration's served inference profiles and stored with that declaration
// generation. An empty inventory asserts no required extension support.
export function newDeclarationWithExtensions() {
  return { declaration: newDeclaration(), supportedExtensions: [] };
}

// The router's latest reading of a host declaration: whether its last survey
// reached the engine, and why it did not.
export function newHostReading() {
  return { up: false, why: "" };
}

// A declaration and the runtime's latest reading of it. role repeats the
// declaration's role, which the runtime resolves for a declaration that names
// none. declared_by is the operator program that declared it, the word
// installation for a declaration file the installation placed beside the
// runtime executable, or the product's own word for a host a product record
// declared. ready means endpoint@1 Describe, over a connection requiring
// program as the server, listed every declared contract ready; for a host it
// means the router's last survey reached it. idle is an on_demand provider
// nothing has needed yet; starting a launched child not yet ready; restarting a
// child that exited and waits out its backoff; refused a process at endpoint
// running another program (why program:<detail>); unreachable a provider whose
// Describe failed (why describe:<code or detail>), or a host the router did not
// reach (why host:<detail>); not_ready a provider whose Describe lists a
// declared contract not ready or absent (why contract:<wire name>:<reason>);
// disabled a declaration of the installation or a product an operator withdrew
// (why operator). described is the last Description's services, and host the
// router's reading of a host. accepted holds the resources a capability
// accepted at the last reading, such as store:<name> described by an inventory
// source and permitted by inventory.provide. restarts counts launches after the
// first.
export function newDeclarationState() {
  return { declaration: newDeclaration(), declaredBy: "", declaredUnixMs: 0n, readiness: "", why: "", restarts: 0n, described: [], accepted: [], role: "", host: null };
}

// page carries every declaration in name order, at most 64, and the
// declarations' revision Declare and Withdraw take. invalid is reserved for a
// request the runtime cannot interpret. Refusals carry an empty revision and no
// declarations.
export function newDeclarationList() {
  return { outcome: "", revision: "", declarations: [] };
}

// applied carries the new revision; the runtime supervises, withdraws or stops
// the provider at once. reason is empty, or rules:<detail> when an acceptance
// rule could not be written. conflict means expected_revision is not current
// (reason revision), or Declare named an existing name or endpoint (reason name
// or endpoint), and carries the current revision. unknown means Withdraw named
// no declaration. invalid carries the field in reason, and program:self when
// the calling program declares itself. Other outcomes carry an empty revision.
export function newDeclarationChange() {
  return { outcome: "", revision: "", reason: "" };
}

// page carries every declaration and cursor, a digest of the declarations and
// their readings. It answers once cursor differs from the cursor given, or when
// wait_ms ends. invalid means wait_ms is outside 0..30000. Refusals carry an
// empty cursor and no declarations.
export function newDeclarationObservation() {
  return { outcome: "", cursor: "", declarations: [] };
}

// The registry@1 state and the extension inventory from the same declaration
// snapshot.
export function newDeclarationStateV2() {
  return { state: newDeclarationState(), supportedExtensions: [] };
}

// The registry@2 declarations and their edit revision. Refusals carry an empty
// revision and no declarations.
export function newDeclarationListV2() {
  return { outcome: "", revision: "", declarations: [] };
}

// The registry@2 declarations and readings from one snapshot. The cursor
// includes extension inventory. Remote server pins are omitted from this
// published projection.
export function newDeclarationObservationV2() {
  return { outcome: "", cursor: "", declarations: [] };
}

// One atomic registry@2 edit: base declaration, extension inventory and
// explicit remote server leaf SPKI SHA-256 pin. A remote edit requires
// remote_server_key_sha256 as 64 lowercase hexadecimal digits; native and HTTP
// edits must omit it. The inventory is validated against served inference
// profiles. All fields are stored in the same declaration generation; the pin
// is configuration, not authentication evidence.
export function newPinnedDeclaration() {
  return { declaration: newDeclaration(), supportedExtensions: [], remoteServerKeySha256: "" };
}

// The registry@1 state, extension inventory and remote server leaf SPKI pin
// from the same declaration snapshot. Old CA-only records have no pin and
// remain inert; native and HTTP records omit it.
export function newPinnedDeclarationState() {
  return { state: newDeclarationState(), supportedExtensions: [], remoteServerKeySha256: "" };
}

// Complete registry@2 configuration and readings at one edit revision. Pins
// configure remote servers; they are not caller or process authentication
// evidence. Refusals carry empty revision and declarations.
export function newPinnedDeclarationList() {
  return { outcome: "", revision: "", declarations: [] };
}

// Complete registry@2 configuration and readings from one snapshot, including
// extension inventory and remote pin changes. Refusals carry empty cursor and
// declarations.
export function newPinnedDeclarationObservation() {
  return { outcome: "", cursor: "", declarations: [] };
}

// The runtime's one reading of whether OpenAbstractions shipped the provider a
// declaration names (A-SEC6). name and program are the declaration's; a reader
// applies standing only to the declaration with that name and program. Only
// product grants a product title or a shipped engine's rank; declared_by and
// the declaration's source grant no standing.
export function newProviderStanding() {
  return { name: "", program: "", standing: "" };
}

// page carries the standing of every declaration in name order, at the edit
// revision Declarations reads. A declaration a reader finds here under another
// program, or not at all, reads as third_party. Refusals carry an empty
// revision and no standings.
export function newProviderStandingList() {
  return { outcome: "", revision: "", standings: [] };
}

// An application's claimed interface metadata. name identifies it within one
// instance; protocol and contract describe claimed support. No connection
// address or executable authority is conveyed. Invocation requires an
// independently authorized OA mediation binding.
export function newApplicationInterface() {
  return { name: "", protocol: "", contract: "" };
}

// Operator-trusted recipe for one bounded start of descriptor.program in the
// owning user's current runtime session. arguments contains at most 64 literal
// arguments of 1..4096 bytes. readiness identifies the interface a
// descriptor-program-and-session-bound announcement must supply.
// readiness_timeout_ms is one 100..30000 budget across executable inspection,
// launch and readiness. The recipe grants no document-open, focus,
// installation, termination or restart authority.
export function newApplicationActivationRecipe() {
  return { arguments: [], readiness: newApplicationInterface(), readinessTimeoutMs: 0n };
}

// Operator-approved installed application. name is a stable 1..64-byte
// identifier; program is its normalized absolute native program identity. title
// and start_guidance are attributed display text, bounded to 256 and 4096
// bytes. Guidance is inert. activation is a separately typed operator-trusted
// recipe; absence disables activation. Registration grants no invocation or
// execution authority. This descriptor survives an application's exit.
export function newApplicationDescriptor() {
  return { name: "", program: "", title: "", startGuidance: "", activation: null };
}

// A bounded application-owned context identifier, display title and revision
// claim. It is scoped to the service-assigned instance epoch; a reused context
// name after restart is a different object. A revision claim supplies no
// authorization or atomic mutation guarantee.
export function newApplicationContext() {
  return { name: "", title: "", revision: "" };
}

// Announce or renew the bound program's own instance in the runtime's verified
// local session. Empty instance requests a new opaque handle; a nonempty handle
// renews exactly its owner and session in the current runtime epoch. At most 16
// distinct interfaces and 32 distinct contexts, each identifier 1..64 bytes.
// The complete JSON-encoded presence is at most 2048 bytes. lease_ms is
// 1000..60000. Expiration establishes absence of fresh evidence, not a clean
// exit.
export function newApplicationPresence() {
  return { application: "", instance: "", interfaces: [], contexts: [], leaseMs: 0n };
}

// A current caller-visible instance and its attributed metadata. Handle
// ownership is enforced by OA. Possession of the handle grants no rights.
export function newApplicationInstance() {
  return { instance: "", interfaces: [], contexts: [], expiresUnixMs: 0n };
}

// One installed application's descriptor with its currently leased instances.
// scope records directory provenance; this local profile supplies local and
// never imports remote announcements. An empty instance list makes no claim
// about whether an unregistered process is running. self_registered is present
// and true while the entry was registered by its own program under the
// account-wide registration default and the person has not answered Keep to the
// runtime's question about it (AskConfirmation). Only such entries carry the
// field.
export function newApplicationEntry() {
  return { descriptor: newApplicationDescriptor(), instances: [], scope: "", selfRegistered: false };
}

// applied confirms the change; an announcement returns its opaque instance.
// stale means the instance expired or belongs to an earlier runtime epoch.
// Refusals carry no instance and never launch an app.
export function newApplicationChange() {
  return { outcome: "", instance: "", reason: "" };
}

// A complete bounded permission-filtered snapshot: at most 64 descriptors and
// 128 total live instances. Cursor is bound to caller, visible state and
// runtime epoch. Observe rechecks permissions before every answer. A cursor
// from another runtime epoch returns stale with a fresh full snapshot; no
// incremental continuity is claimed. Outcomes other than page or stale carry no
// cursor or entries.
export function newApplicationPage() {
  return { outcome: "", cursor: "", applications: [] };
}

// ready identifies a descriptor-program-and-session-bound presence whose
// claimed interface matches the recipe; it is not a protocol probe or
// process-lineage proof. started says the platform launcher accepted the recipe
// during this shared attempt; the returned instance may be a fresh announcement
// from an already-running matching program. false means an existing matching
// instance was reused before launch. Cancellation returns unavailable to that
// waiter and leaves the bounded attempt and user application alive. Failure
// outcomes carry no instance.
export function newApplicationActivationResult() {
  return { outcome: "", instance: "", started: false, reason: "" };
}

// One time an application became present in this runtime: the first announced
// instance of a registered application in a local session where none of its
// instances was live. application, program and title are the descriptor's at
// that time. launched is true when this runtime's own activation attempt for
// the application in that session was waiting for it; false means the
// application announced itself. It records a fresh announcement, not process
// lineage, and a runtime restart makes every running application announce
// again.
export function newApplicationStart() {
  return { application: "", program: "", title: "", startedUnixMs: 0n, launched: false };
}

// page carries at most the requested 1..64 starts, newest first. complete means
// the log was exhausted; otherwise cursor continues it. complete_since_unix_ms
// is zero while every retained start is listed; otherwise starts at or before
// it may have been evicted. stale means the cursor's log changed or belongs to
// another runtime: restart from an empty cursor. Other outcomes carry no starts
// or cursor.
export function newApplicationStartPage() {
  return { outcome: "", starts: [], cursor: "", complete: false, completeSinceUnixMs: 0n };
}

